#!/usr/bin/env python3

from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[4]
ENUM_DIR = ROOT / "Content.Shared.Database"
OUT = Path(__file__).resolve().parents[1] / "admin_assist" / "logtypes.py"

_MEMBER = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(-?\d+)", re.M)


def parse_enum(path: Path) -> list[tuple[str, int]]:
    return [(name, int(value)) for name, value in _MEMBER.findall(path.read_text(encoding="utf-8-sig"))]


def render() -> str:
    lines = [
        '"""GENERATED by scripts/gen_logtypes.py from Content.Shared.Database. Do not edit."""',
        "",
        "from enum import IntEnum",
    ]
    for cls, filename in (("LogType", "LogType.cs"), ("LogImpact", "LogImpact.cs")):
        lines += ["", "", f"class {cls}(IntEnum):"]
        lines += [f"    {name} = {value}" for name, value in parse_enum(ENUM_DIR / filename)]
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    OUT.write_text(render(), encoding="utf-8")
    print(f"wrote {OUT}")
